import fs from 'fs';
import { ethers } from 'ethers';
import dotenv from 'dotenv';

// Load .env locally (GitHub Actions will inject these variables automatically)
dotenv.config();

async function main() {
  // 1. Read the output generated by your Docker solc build

  const outputPath = './build/combined.json';
  if (!fs.existsSync(outputPath)) {
    throw new Error("build/combined.json not found. Run 'npm run compile' first.");
  }
  const output = JSON.parse(fs.readFileSync(outputPath, 'utf8'));

  // 2. Extract the ABI and Bytecode for YieldVault
  const contractName = "YieldVault";
  const sourceFile = Object.keys(output.contracts).find(key => key.includes(contractName));
  
  if (!sourceFile) {
    throw new Error(`Contract ${contractName} not found in build output.`);
  }

  const contractData = output.contracts[sourceFile][contractName];
  const abi = contractData.abi;
  const bytecode = contractData.evm.bytecode.object;

  // 3. Connect to Sepolia
  const provider = new ethers.JsonRpcProvider(process.env.SEPOLIA_RPC_URL);
  
  // 4. Bulletproof Private Key Sanitization
  let rawKey = (process.env.SEPOLIA_PRIVATE_KEY || "")
    .trim()
    .replace(/^["']|["']$/g, '') // Remove quotes
    .replace(/\s+/g, '');        // Remove ALL spaces and newlines

  // Ensure it has the 0x prefix (Ethers.js v6 requires this)
  if (!rawKey.startsWith("0x")) {
    rawKey = "0x" + rawKey;
  }

  if (rawKey.length !== 66) {
    throw new Error(`Invalid private key length: ${rawKey.length}. Expected 66 characters (0x + 64 hex chars).`);
  }

  const wallet = new ethers.Wallet(rawKey, provider);
  console.log("Deploying contracts with the account:", wallet.address);

  // 5. Define constructor arguments
  // Sepolia USDC test address used as an example. Replace if using your own token.
  const assetAddress = "0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238"; 
  const name = "Yield Vault Share";
  const symbol = "yvSHARE";
  const initialOwner = wallet.address;
  const feeRecipient = wallet.address;
  const performanceFeeBps = 1000; // 10%
  const depositCap = ethers.parseUnits("1000000", 18);

  // 6. Deploy
  console.log("Deploying YieldVault...");
  const factory = new ethers.ContractFactory(abi, bytecode, wallet);
  
  const vault = await factory.deploy(
    assetAddress,
    name,
    symbol,
    initialOwner,
    feeRecipient,
    performanceFeeBps,
    depositCap
  );

  await vault.waitForDeployment();
  const contractAddress = await vault.getAddress();
  
  console.log(`YieldVault successfully deployed to: ${contractAddress}`);
  console.log(`View on Sepolia Etherscan: https://sepolia.etherscan.io/address/${contractAddress}`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
